import{_ as n,a0 as s,w as a,s as r,ao as p,I as d,x as t,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"面向系統管理員的網絡管理指南 | LCTT x X-CMD","titleTemplate":false,"description":"面向系統管理員的網絡管理指南 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"面向系統管理員的網絡管理指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"面向系統管理員的網絡管理指南 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180709 A sysadmin-s guide to network management","title":"面向系統管理員的網絡管理指南","tag":"201808","desc":""},"relativePath":"201808/20180709 A sysadmin-s guide to network management.md","filePath":"[post].md"}'),c={name:"201808/20180709 A sysadmin-s guide to network management.md"};function u(g,e,m,f,P,h){const o=s("Link");return a(),r("div",null,[e[28]||(e[28]=p('<h1 id="面向系統管理員的網絡管理指南" tabindex="-1">面向系統管理員的網絡管理指南 <a class="header-anchor" href="#面向系統管理員的網絡管理指南" aria-label="Permalink to “面向系統管理員的網絡管理指南”">​</a></h1><blockquote><p>一個使管理服務器和網絡更輕鬆的 Linux 工具和命令的參考列表。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/openwires_fromRHT_520_0612LL.png?itok=PqZi55Ab" alt=""></p><p>如果你是一位系統管理員，那麼你的日常工作應該包括管理服務器和數據中心的網絡。以下的 Linux 實用工具和命令 —— 從基礎的到高級的 —— 將幫你更輕鬆地管理你的網絡。</p><p>在幾個命令中，你將會看到 <code>&lt;fqdn&gt;</code>，它是“完全合格域名”的全稱。當你看到它時，你應該用你的網站 URL 或你的服務器來代替它（比如，<code>server-name.company.com</code>），具體要視情況而定。</p><h3 id="ping" tabindex="-1">Ping <a class="header-anchor" href="#ping" aria-label="Permalink to “Ping”">​</a></h3>',6)),d("p",null,[e[2]||(e[2]=t("正如它的名字所表示的那樣，",-1)),e[3]||(e[3]=d("code",null,"ping",-1)),e[4]||(e[4]=t(" 是用於去檢查從你的系統到你想去連接的系統之間端到端的連通性。當一個 ping 成功時，它使用的 ",-1)),l(o,{href:"https://en.wikipedia.org/wiki/Internet_Control_Message_Protocol"},{default:i(()=>[...e[0]||(e[0]=[t("ICMP",-1)])]),_:1}),e[5]||(e[5]=t(" 的 echo 包將會返回到你的系統中。它是檢查系統/網絡連通性的一個良好開端。你可以在 IPv4 和 IPv6 地址上使用 ",-1)),e[6]||(e[6]=d("code",null,"ping",-1)),e[7]||(e[7]=t(' 命令。（閲讀我的文章 "',-1)),l(o,{href:"https://opensource.com/article/18/5/how-find-ip-address-linux"},{default:i(()=>[...e[1]||(e[1]=[t("如何在 Linux 系統上找到你的 IP 地址",-1)])]),_:1}),e[8]||(e[8]=t('" 去學習更多關於 IP 地址的知識）',-1))]),e[29]||(e[29]=p('<p><strong>語法：</strong></p><ul><li>IPv4: <code>ping &lt;ip address&gt;/&lt;fqdn&gt;</code></li><li>IPv6: <code>ping6 &lt;ip address&gt;/&lt;fqdn&gt;</code></li></ul><p>你也可以使用 <code>ping</code> 去解析出網站所對應的 IP 地址，如下圖所示：</p><p><img src="https://opensource.com/sites/default/files/uploads/ping-screen-0.png" alt=""></p><h3 id="traceroute" tabindex="-1">Traceroute <a class="header-anchor" href="#traceroute" aria-label="Permalink to “Traceroute”">​</a></h3><p><code>ping</code> 是用於檢查端到端的連通性，<code>traceroute</code> 實用工具將告訴你到達對端系統、網站、或服務器所經過的路徑上所有路由器的 IP 地址。<code>traceroute</code> 在網絡連接調試中經常用於在 <code>ping</code> 之後的第二步。</p><p>這是一個跟蹤從你的系統到其它對端的全部網絡路徑的非常好的工具。在檢查端到端的連通性時，這個實用工具將告訴你到達對端系統、網站、或服務器上所經歷的路徑上的全部路由器的 IP 地址。通常用於網絡連通性調試的第二步。</p><p><strong>語法：</strong></p><ul><li><code>traceroute &lt;ip address&gt;/&lt;fqdn&gt;</code></li></ul><h3 id="telnet" tabindex="-1">Telnet <a class="header-anchor" href="#telnet" aria-label="Permalink to “Telnet”">​</a></h3><p><strong>語法：</strong></p>',11)),d("ul",null,[d("li",null,[e[10]||(e[10]=d("code",null,"telnet <ip address>/<fqdn>",-1)),e[11]||(e[11]=t(" 是用於 ",-1)),l(o,{href:"https://en.wikipedia.org/wiki/Telnet"},{default:i(()=>[...e[9]||(e[9]=[t("telnet",-1)])]),_:1}),e[12]||(e[12]=t(" 進入任何支持該協議的服務器。",-1))])]),e[30]||(e[30]=p('<h3 id="netstat" tabindex="-1">Netstat <a class="header-anchor" href="#netstat" aria-label="Permalink to “Netstat”">​</a></h3><p>這個網絡統計（<code>netstat</code>）實用工具是用於去分析解決網絡連接問題和檢查接口/端口統計數據、路由表、協議狀態等等的。它是任何管理員都應該必須掌握的工具。</p><p><strong>語法：</strong></p><ul><li><code>netstat -l</code> 顯示所有處於監聽狀態的端口列表。</li><li><code>netstat -a</code> 顯示所有端口；如果去指定僅顯示 TCP 端口，使用 <code>-at</code>（指定信顯示 UDP 端口，使用 <code>-au</code>）。</li><li><code>netstat -r</code> 顯示路由表。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/netstat-r.png" alt=""></p><ul><li><code>netstat -s</code> 顯示每個協議的狀態總結。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/netstat-s.png" alt=""></p><ul><li><code>netstat -i</code> 顯示每個接口傳輸/接收（TX/RX）包的統計數據。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/netstat-i.png" alt=""></p><h3 id="nmcli" tabindex="-1">Nmcli <a class="header-anchor" href="#nmcli" aria-label="Permalink to “Nmcli”">​</a></h3><p><code>nmcli</code> 是一個管理網絡連接、配置等工作的非常好的實用工具。它能夠去管理網絡管理程序和修改任何設備的網絡配置詳情。</p><p><strong>語法：</strong></p><ul><li><code>nmcli device</code> 列出網絡上的所有設備。</li><li><code>nmcli device show &lt;interface&gt;</code> 顯示指定接口的網絡相關的詳細情況。</li><li><code>nmcli connection</code> 檢查設備的連接情況。</li><li><code>nmcli connection down &lt;interface&gt;</code> 關閉指定接口。</li><li><code>nmcli connection up &lt;interface&gt;</code> 打開指定接口。</li><li><code>nmcli con add type vlan con-name &lt;connection-name&gt; dev &lt;interface&gt; id &lt;vlan-number&gt; ipv4 &lt;ip/cidr&gt; gw4 &lt;gateway-ip&gt;</code> 在特定的接口上使用指定的 VLAN 號添加一個虛擬局域網（VLAN）接口、IP 地址、和網關。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/nmcli.png" alt=""></p><h3 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to “路由”">​</a></h3><p>檢查和配置路由的命令很多。下面是其中一些比較有用的：</p><p><strong>語法：</strong></p><ul><li><code>ip route</code> 顯示各自接口上所有當前的路由配置。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/ip-route.png" alt=""></p><ul><li><code>route add default gw &lt;gateway-ip&gt;</code> 在路由表中添加一個默認的網關。</li><li><code>route add -net &lt;network ip/cidr&gt; gw &lt;gateway ip&gt; &lt;interface&gt;</code> 在路由表中添加一個新的網絡路由。還有許多其它的路由參數，比如，添加一個默認路由，默認網關等等。</li><li><code>route del -net &lt;network ip/cidr&gt;</code> 從路由表中刪除一個指定的路由條目。</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/route-add-del.png" alt=""></p><ul><li><p><code>ip neighbor</code> 顯示當前的鄰接表和用於去添加、改變、或刪除新的鄰居。</p><p><img src="https://opensource.com/sites/default/files/uploads/ip-neighbor.png" alt=""></p><p><img src="https://opensource.com/sites/default/files/uploads/ip-neigh-help.png" alt=""></p></li><li><p><code>arp</code> （它的全稱是 “地址解析協議”）類似於 <code>ip neighbor</code>。<code>arp</code> 映射一個系統的 IP 地址到它相應的 MAC（介質訪問控制）地址。</p><p><img src="https://opensource.com/sites/default/files/uploads/arp.png" alt=""></p></li></ul><h3 id="tcpdump-和-wireshark" tabindex="-1">Tcpdump 和 Wireshark <a class="header-anchor" href="#tcpdump-和-wireshark" aria-label="Permalink to “Tcpdump 和 Wireshark”">​</a></h3><p>Linux 提供了許多包捕獲工具，比如 <code>tcpdump</code>、<code>wireshark</code>、<code>tshark</code> 等等。它們被用於去捕獲傳輸/接收的網絡流量中的數據包，因此它們對於系統管理員去診斷丟包或相關問題時非常有用。對於熱衷於命令列操作的人來説，<code>tcpdump</code> 是一個非常好的工具，而對於喜歡 GUI 操作的用户來説，<code>wireshark</code> 是捕獲和分析數據包的不二選擇。<code>tcpdump</code> 是一個 Linux 內置的用於去捕獲網絡流量的實用工具。它能夠用於去捕獲/顯示特定端口、協議等上的流量。</p><p><strong>語法：</strong></p><ul><li><p><code>tcpdump -i &lt;interface-name&gt;</code> 顯示指定接口上實時通過的數據包。通過在命令中添加一個 <code>-w</code> 標誌和輸出文件的名字，可以將數據包保存到一個文件中。例如：<code>tcpdump -w &lt;output-file.&gt; -i &lt;interface-name&gt;</code>。</p><p><img src="https://opensource.com/sites/default/files/uploads/tcpdump-i.png" alt=""></p></li><li><p><code>tcpdump -i &lt;interface&gt; src &lt;source-ip&gt;</code> 從指定的源 IP 地址上捕獲數據包。</p></li><li><p><code>tcpdump -i &lt;interface&gt; dst &lt;destination-ip&gt;</code> 從指定的目標 IP 地址上捕獲數據包。</p></li><li><p><code>tcpdump -i &lt;interface&gt; port &lt;port-number&gt;</code> 從一個指定的端口號（比如，53、80、8080 等等）上捕獲數據包。</p></li><li><p><code>tcpdump -i &lt;interface&gt; &lt;protocol&gt;</code> 捕獲指定協議的數據包，比如：TCP、UDP、等等。</p></li></ul><h3 id="iptables" tabindex="-1">Iptables <a class="header-anchor" href="#iptables" aria-label="Permalink to “Iptables”">​</a></h3><p><code>iptables</code> 是一個包過濾防火牆工具，它能夠允許或阻止某些流量。這個實用工具的應用範圍非常廣泛；下面是它的其中一些最常用的使用命令。</p><p><strong>語法：</strong></p><ul><li><code>iptables -L</code> 列出所有已存在的 <code>iptables</code> 規則。</li><li><code>iptables -F</code> 刪除所有已存在的規則。</li></ul><p>下列命令允許流量從指定端口到指定接口：</p><ul><li><code>iptables -A INPUT -i &lt;interface&gt; -p tcp –dport &lt;port-number&gt; -m state –state NEW,ESTABLISHED -j ACCEPT</code></li><li><code>iptables -A OUTPUT -o &lt;interface&gt; -p tcp -sport &lt;port-number&gt; -m state – state ESTABLISHED -j ACCEPT</code></li></ul><p>下列命令允許<ruby>環回<rt>loopback</rt></ruby>接口訪問系統：</p><ul><li><code>iptables -A INPUT -i lo -j ACCEPT</code></li><li><code>iptables -A OUTPUT -o lo -j ACCEPT</code></li></ul><h3 id="nslookup" tabindex="-1">Nslookup <a class="header-anchor" href="#nslookup" aria-label="Permalink to “Nslookup”">​</a></h3><p><code>nslookup</code> 工具是用於去獲得一個網站或域名所映射的 IP 地址。它也能用於去獲得你的 DNS 服務器的信息，比如，一個網站的所有 DNS 記錄（具體看下面的示例）。與 <code>nslookup</code> 類似的一個工具是 <code>dig</code>（Domain Information Groper）實用工具。</p><p><strong>語法：</strong></p><ul><li><code>nslookup &lt;website-name.com&gt;</code> 顯示你的服務器組中 DNS 服務器的 IP 地址，它後面就是你想去訪問網站的 IP 地址。</li><li><code>nslookup -type=any &lt;website-name.com&gt;</code> 顯示指定網站/域中所有可用記錄。</li></ul><h3 id="網絡-接口調試" tabindex="-1">網絡/接口調試 <a class="header-anchor" href="#網絡-接口調試" aria-label="Permalink to “網絡/接口調試”">​</a></h3><p>下面是用於接口連通性或相關網絡問題調試所需的命令和文件的彙總。</p><p><strong>語法：</strong></p><ul><li><code>ss</code> 是一個轉儲套接字統計數據的實用工具。</li><li><code>nmap &lt;ip-address&gt;</code>，它的全稱是 “Network Mapper”，它用於掃描網絡端口、發現主機、檢測 MAC 地址，等等。</li><li><code>ip addr/ifconfig -a</code> 提供一個系統上所有接口的 IP 地址和相關信息。</li><li><code>ssh -vvv user@&lt;ip/domain&gt;</code> 允許你使用指定的 IP/域名和用户名通過 SSH 協議登入到其它服務器。<code>-vvv</code> 標誌提供 SSH 登入到服務器過程中的 &quot;最詳細的&quot; 信息。</li><li><code>ethtool -S &lt;interface&gt;</code> 檢查指定接口上的統計數據。</li><li><code>ifup &lt;interface&gt;</code> 啓動指定的接口。</li><li><code>ifdown &lt;interface&gt;</code> 關閉指定的接口</li><li><code>systemctl restart network</code> 重啓動系統上的一個網絡服務。</li><li><code>/etc/sysconfig/network-scripts/&lt;interface-name&gt;</code> 是一個對指定的接口設置 IP 地址、網絡、網關等等的接口配置文件。DHCP 模式也可以在這裏設置。</li><li><code>/etc/hosts</code> 這個文件包含自定義的主機/域名到 IP 地址的映射。</li><li><code>/etc/resolv.conf</code> 指定系統上的 DNS 服務器的 IP 地址。</li><li><code>/etc/ntp.conf</code> 指定 NTP 服務器域名。</li></ul><hr>',43)),d("p",null,[e[14]||(e[14]=t("via: ",-1)),l(o,{href:"https://opensource.com/article/18/7/sysadmin-guide-networking-commands"},{default:i(()=>[...e[13]||(e[13]=[t("https://opensource.com/article/18/7/sysadmin-guide-networking-commands",-1)])]),_:1})]),d("p",null,[e[19]||(e[19]=t("作者：",-1)),l(o,{href:"https://opensource.com/users/architmodi"},{default:i(()=>[...e[15]||(e[15]=[t("Archit Modi",-1)])]),_:1}),e[20]||(e[20]=t(" 選題：",-1)),l(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[16]||(e[16]=[t("lujun9972",-1)])]),_:1}),e[21]||(e[21]=t(" 譯者：",-1)),l(o,{href:"https://github.com/qhwdw"},{default:i(()=>[...e[17]||(e[17]=[t("qhwdw",-1)])]),_:1}),e[22]||(e[22]=t(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[18]||(e[18]=[t("wxy",-1)])]),_:1})]),d("p",null,[e[25]||(e[25]=t("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[23]||(e[23]=[t("LCTT",-1)])]),_:1}),e[26]||(e[26]=t(" 原創編譯，",-1)),l(o,{href:"https://linux.cn/"},{default:i(()=>[...e[24]||(e[24]=[t("Linux中國",-1)])]),_:1}),e[27]||(e[27]=t(" 榮譽推出",-1))])])}const w=n(c,[["render",u]]);export{k as __pageData,w as default};
